sp_widget.css:
.dept-profile{

padding-bottom:40px;

}



/* HERO */

.hero{

position:relative;

overflow:hidden;

min-height:320px;

padding:58px 70px;

border-radius:36px;

background:
linear-gradient(
135deg,
#071733,
#1D46D5
);

display:flex;

justify-content:
space-between;

align-items:
flex-start;

color:white;

}



.overlay{

position:absolute;

right:-120px;

top:-100px;

width:480px;

height:480px;

border-radius:50%;

background:
rgba(
255,
255,
255,
.08
);

}



/* LEFT */

.hero-content{

position:relative;

z-index:2;

max-width:760px;

padding-top:20px;

}



/* TITLE */

.hero h1{

margin:0;

font-size:64px;

font-weight:900;

line-height:1;

}



/* DESCRIPTION */

.subtitle{

margin-top:26px;

font-size:20px;

line-height:1.8;

opacity:.92;

max-width:760px;

}



/* BUTTONS MOVED BELOW TITLE */

.hero-top{

display:flex;

gap:18px;

align-items:center;

margin-top:36px;

}



.back-btn{

width:150px;

height:56px;

border:none;

border-radius:18px;

background:
rgba(
255,
255,
255,
.12
);

color:white;

font-size:18px;

font-weight:800;

cursor:pointer;

}



.badge{

height:56px;

padding:0 28px;

display:flex;

align-items:center;

border-radius:999px;

background:
rgba(
255,
255,
255,
.12
);

font-size:18px;

font-weight:800;

}



/* RIGHT ICON */

.avatar{

width:170px;

height:170px;

border-radius:40px;

background:
rgba(
255,
255,
255,
.10
);

display:flex;

justify-content:center;

align-items:center;

font-size:82px;

position:relative;

z-index:2;

margin-top:70px;

margin-right:18px;

flex-shrink:0;

}



/* DETAILS */

.content-grid{

display:grid;

grid-template-columns:
1fr 1fr;

gap:28px;

margin-top:34px;

}



.card{

background:white;

border-radius:28px;

padding:32px;

}



.card h2{

margin-bottom:24px;

color:#0B2A79;

font-size:22px;

}



/* FIELD */

.field{

padding:24px;

background:#F5F7FD;

border-radius:18px;

margin-bottom:18px;

}



.field label{

display:block;

font-size:12px;

margin-bottom:10px;

color:#666;

}



.field div{

font-size:18px;

font-weight:800;

color:#0B2A79;

}



/* MEMBERS */

.member{

display:flex;

gap:18px;

padding:18px;

background:#F5F7FD;

border-radius:18px;

margin-bottom:14px;

}



.member-avatar{

width:62px;

height:62px;

border-radius:18px;

background:#2F62F5;

color:white;

display:flex;

justify-content:center;

align-items:center;

font-size:26px;

}



.member-name{

font-size:18px;

font-weight:800;

}



.member-role{

margin-top:6px;

color:#7283A6;

}



.empty{

padding:24px;

text-align:center;

color:#7B89A5;

}



/* MOBILE */

@media(max-width:900px){

.hero{

flex-direction:column;

padding:34px;

gap:26px;

}



.hero h1{

font-size:42px;

}



.hero-top{

flex-wrap:wrap;

margin-top:24px;

}



.avatar{

margin:auto;

width:130px;

height:130px;

font-size:64px;

}



.content-grid{

grid-template-columns:
1fr;

}

}

sp_widget.script:
(function(){
    data.department = {};
    data.members = [];

    var id = $sp.getParameter('sys_id');
    if(!id) return;

    var dep = new GlideRecord('x_1902481_employ_0_department');
    if(dep.get(id)){

        var deptName = dep.getValue('department_name') || '';

        data.department = {
            name: deptName,
            description: dep.getValue('description') || '',
            head: dep.getDisplayValue('department_head') || '-',
            company: dep.getDisplayValue('company') || '-',
            employee_count: 0
        };

        // Count by department NAME
        var ga = new GlideAggregate('x_1902481_employ_0_employee');
        ga.addQuery('department', deptName);
        ga.addAggregate('COUNT');
        ga.query();
        if(ga.next()){
            data.department.employee_count = ga.getAggregate('COUNT');
        }

        // Get members by department NAME
        var emp = new GlideRecord('x_1902481_employ_0_employee');
        emp.addQuery('department', deptName);
        emp.query();
        while(emp.next()){
            data.members.push({
                name: emp.getDisplayValue('first_name') + ' ' + emp.getDisplayValue('last_name'),
                designation: emp.getValue('designation') || '',
                initial: (emp.getValue('first_name') || 'E').substring(0, 1)
            });
        }
    }
})();
